-- Livelier names for workshops 3 and 6, and interactive summaries and
-- descriptions for workshops 1, 3, 4, 5 and 6 (workshop 2 was already done
-- in setup SQL 30). URLs are unchanged.
begin;
update public.workshops set summary = 'An interactive session on turning your research into a published paper, from first draft to acceptance.', description = 'This is a hands-on session, not a lecture. In small groups, you''ll follow a piece of research from first draft to published paper: working out how a strong manuscript is structured, weighing up which journal suits the work, unpicking what happens in peer review and practising how to respond to reviewers. You''ll leave with a realistic plan for publishing your own work, so bring your questions about any project you''re working on.'
 where number = 1 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Don''t Believe the Headline: Spotting Research You Can Trust', strapline = 'Read critically. Decide well.', summary = 'Work through published research together and learn to tell a strong study from a weak one, a skill you''ll use in journal clubs, exams and on the wards.', description = 'Not every published study should change practice. In this interactive session you''ll work through published research in groups, test how valid and relevant it is, and hunt for the biases that can mislead. Then you''ll debate how the evidence should be weighed alongside clinical judgement and what matters most to the patient, and leave with a structured approach you can use on any paper.'
 where number = 3 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set summary = 'An interactive session on capturing your achievements, finding the right opportunities and building a portfolio that tells your story.', description = 'A strong portfolio shows what you''ve done and where you''re heading. In this interactive session you''ll set up a simple way to record your achievements as you go, map out opportunities in research, teaching and leadership that match your interests, and practise presenting your experience clearly and honestly. Expect discussion, ideas from other students and plenty of time for your questions.'
 where number = 4 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set summary = 'An interactive look at how simulation and emerging digital tools are changing the way surgeons train and operate.', description = 'From simulation-based training to new digital tools in theatre, technology is reshaping surgery. In this interactive session you''ll explore how these tools are used in surgical education and practice, discuss what the evidence says about their benefits, and work out together how new technology should be judged before it reaches patients. Any hands-on demonstrations or equipment will be announced once confirmed by the facilitators.'
 where number = 5 and edition_id = (select id from public.editions where year = 2026);
update public.workshops set title = 'Left Offline: Global Digital Health Inequalities', strapline = 'Who benefits from digital health, and who is left behind?', summary = 'An interactive session on why the same technology can transform care for some people and shut others out, in the UK and around the world.', description = 'Digital health can narrow inequalities or make them worse. In this interactive session you''ll work in groups to explore how access, connectivity, digital literacy, income and the design of health systems decide who benefits from new technology, in the UK and globally. Then you''ll put your heads together on what fairer digital health could look like.'
 where number = 6 and edition_id = (select id from public.editions where year = 2026);
commit;
